export const TodoRow = memo(function TodoRow({ todo, onToggle, onRender }) {
  onRender?.(todo.id)
  return (
    <li>
      <label><input type="checkbox" checked={todo.done} onChange={() => onToggle(todo.id)} /> {todo.text}</label>
    </li>
  )
})

export function TodoList({ todos, onToggle, onRowRender }) {
  return <ul>{todos.map((t) => <TodoRow key={t.id} todo={t} onToggle={onToggle} onRender={onRowRender} />)}</ul>
}

