import { render, screen, fireEvent, act } from '@testing-library/react'
import { expect, test } from 'vitest'
import { useCallback, useState } from 'react'
import { TodoList } from './TodoList'

function App({ log }) {
  const [todos, setTodos] = useState([{ id: 1, text: 'a', done: false }, { id: 2, text: 'b', done: false }, { id: 3, text: 'c', done: false }])
  const onToggle = useCallback((id) => setTodos((ts) => ts.map((t) => (t.id === id ? { ...t, done: !t.done } : t))), [])
  const onRowRender = useCallback((id) => log.push(id), [log])
  return <TodoList todos={todos} onToggle={onToggle} onRowRender={onRowRender} />
}

test('renders all rows', () => {
  render(<App log={[]} />)
  expect(screen.getAllByRole('checkbox')).toHaveLength(3)
})

test('toggling works', () => {
  render(<App log={[]} />)
  fireEvent.click(screen.getAllByRole('checkbox')[1])
  expect(screen.getAllByRole('checkbox').map((c) => c.checked)).toEqual([false, true, false])
})

test('only the changed row re-renders', () => {
  const log = []
  render(<App log={log} />)
  log.length = 0
  fireEvent.click(screen.getAllByRole('checkbox')[1])
  expect(log).toEqual([2])
})

