import { memo, useCallback, useMemo, useState } from 'react'

const Chart = memo(function Chart({ points, onPick, onRender }) {
  onRender?.()
  return <output onClick={() => onPick(points[0])}>{points.length}</output>
})

export function Dashboard({ rows, onChartRender }) {
  const [theme, setTheme] = useState('light')
  const points = useMemo(() => rows.map((r) => r.value), [rows])
  const onPick = useCallback(() => {}, [])
  return (
    <div className={theme}>
      <button onClick={() => setTheme((t) => (t === 'light' ? 'dark' : 'light'))}>theme</button>
      <Chart points={points} onPick={onPick} onRender={onChartRender} />
    </div>
  )
}

