import { useState } from 'react'

export function ExpandablePanel({ title, children }) {
  const [open, setOpen] = useState(true)
  const [clicks, setClicks] = useState(0)
  return (
    <section>
      <button aria-expanded={open} onClick={() => { setOpen((o) => !o); setClicks((c) => c + 1) }}>{title} ({clicks})</button>
      <div hidden={!open}>{children}</div>
    </section>
  )
}

