import { Suspense } from 'react'
import { lazyWithPreload } from './lazyWithPreload'

const mod = (text) => Promise.resolve({ default: () => <p>{text}</p> })

test('renders through Suspense', async () => {
  const C = lazyWithPreload(() => mod('settings'))
  render(<Suspense fallback={<i>loading</i>}><C /></Suspense>)
  expect(await screen.findByText('settings')).toBeTruthy()
})

test('preload starts loading before render', () => {
  let calls = 0
  const C = lazyWithPreload(() => { calls++; return mod('x') })
  C.preload()
  expect(calls).toBe(1)
})

test('factory runs only once', async () => {
  let calls = 0
  const C = lazyWithPreload(() => { calls++; return mod('once') })
  C.preload(); C.preload()
  render(<Suspense fallback={null}><C /></Suspense>)
  await screen.findByText('once')
  expect(calls).toBe(1)
})

