export function getVirtualRange({ count, itemHeight, viewportHeight, scrollTop, overscan = 3 }) {
  const first = Math.floor(scrollTop / itemHeight)
  const visible = Math.ceil(viewportHeight / itemHeight)
  const start = Math.max(0, first - overscan)
  const end = Math.min(count, first + visible + overscan)
  return { start, end, offsetTop: start * itemHeight, totalHeight: count * itemHeight }
}

