export function createRenderStats() {
  const data = {}
  const r = (n) => Math.round(n * 100) / 100
  return {
    onRender(id, phase, actualDuration) {
      const e = (data[id] ??= { commits: 0, mounts: 0, totalMs: 0, maxMs: 0 })
      e.commits++
      if (phase === 'mount') e.mounts++
      e.totalMs = r(e.totalMs + actualDuration)
      e.maxMs = r(Math.max(e.maxMs, actualDuration))
    },
    report: () => data,
  }
}

