import { render, screen, fireEvent, act } from '@testing-library/react'
import { expect, test } from 'vitest'
import { Profiler, useState } from 'react'
import { createRenderStats } from './renderStats'

test('aggregates calls by id', () => {
  const s = createRenderStats()
  s.onRender('a', 'mount', 2.111)
  s.onRender('a', 'update', 5)
  s.onRender('b', 'mount', 1)
  expect(s.report()).toEqual({ a: { commits: 2, mounts: 1, totalMs: 7.11, maxMs: 5 }, b: { commits: 1, mounts: 1, totalMs: 1, maxMs: 1 } })
