test('works with the Profiler component', () => {
  const s = createRenderStats()
  function C() { const [n, setN] = useState(0); return <button onClick={() => setN(n + 1)}>{n}</button> }
  render(<Profiler id="btn" onRender={s.onRender}><C /></Profiler>)
  fireEvent.click(screen.getByRole('button'))
  expect(s.report().btn.commits).toBe(2)
  expect(s.report().btn.mounts).toBe(1)
})

